package com.fireplatform;

import com.fireplatform.devicegroup.DeviceGroupConflicts;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.assertj.core.api.Assertions.*;

class DeviceGroupMigrationTest {
    record Db(String url,JdbcTemplate jdbc) { }
    Db db(boolean latest){String url="jdbc:h2:mem:devicegroup-migration-"+UUID.randomUUID()+";MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";var flyway=Flyway.configure().dataSource(url,"sa","");flyway.target(latest?"13":"12");flyway.load().migrate();return new Db(url,new JdbcTemplate(new DriverManagerDataSource(url,"sa","")));}
    void latest(Db db){Flyway.configure().dataSource(db.url(),"sa","").target("13").load().migrate();}
    List<String> tables(JdbcTemplate j){return j.queryForList("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name",String.class);}
    Map<String,Object> facts(JdbcTemplate j,List<String> tables){var all=new TreeMap<String,Object>();for(String table:tables)if(!table.equals("flyway_schema_history"))all.put(table,j.queryForList("SELECT * FROM "+table));return all;}
    void group(JdbcTemplate j,String id,String tenant,String name){j.update("INSERT INTO device_groups(id,tenant_id,name,description,revision) VALUES (?,?,?,'',0)",id,tenant,name);}
    void fixtures(JdbcTemplate j){j.update("INSERT INTO tenants(id,name) VALUES ('a','A'),('b','B')");for(String tenant:List.of("a","b"))j.update("INSERT INTO devices(id,tenant_id,name,device_eui,model,address,physical_state) VALUES (?,?,?,?,'m','','NORMAL')","legacy/"+tenant+"%?#",tenant,tenant,"eui-"+tenant);}
    @Test void emptyLatestCreatesExactlyTwoEmptyTablesWithoutSeedOrPermissionChange(){var db=db(true);var j=db.jdbc();assertThat(tables(j)).hasSize(46);for(String table:List.of("device_groups","device_group_members"))assertThat(j.queryForObject("SELECT COUNT(*) FROM "+table,Long.class)).isZero();assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='device_group_members'",String.class)).containsExactlyInAnyOrder("tenant_id","group_id","device_id");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='device_groups'",String.class)).containsExactlyInAnyOrder("id","tenant_id","name","description","revision");assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions",Long.class)).isZero();}
    @Test void v12UpgradePreservesEveryOldFactColumnConstraintAndDeviceIndex(){var db=db(false);var j=db.jdbc();fixtures(j);var old=tables(j);assertThat(old).hasSize(44);var facts=facts(j,old);var columns=j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' ORDER BY table_name,ordinal_position");var indexes=j.queryForList("SELECT * FROM information_schema.indexes WHERE table_name='devices' ORDER BY index_name");var constraints=j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public' ORDER BY table_name,constraint_name");latest(db);assertThat(tables(j)).hasSize(46).containsAll(old);assertThat(facts(j,old)).isEqualTo(facts);assertThat(j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name NOT IN ('device_groups','device_group_members') ORDER BY table_name,ordinal_position")).isEqualTo(columns);assertThat(j.queryForList("SELECT * FROM information_schema.indexes WHERE table_name='devices' ORDER BY index_name")).isEqualTo(indexes);assertThat(j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public' AND table_name NOT IN ('device_groups','device_group_members') ORDER BY table_name,constraint_name")).isEqualTo(constraints);}
    @Test void compositeTenantForeignKeysRejectBothCrossUnitPairingsAtDatabaseBoundary(){var db=db(true);var j=db.jdbc();fixtures(j);String a=UUID.randomUUID().toString(),b=UUID.randomUUID().toString();group(j,a,"a","A");group(j,b,"b","B");assertThatThrownBy(()->j.update("INSERT INTO device_group_members(tenant_id,group_id,device_id) VALUES ('b',?,'legacy/b%?#')",a)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->j.update("INSERT INTO device_group_members(tenant_id,group_id,device_id) VALUES ('a',?,'legacy/b%?#')",a)).isInstanceOf(DataAccessException.class);j.update("INSERT INTO device_group_members(tenant_id,group_id,device_id) VALUES ('b',?,'legacy/b%?#')",b);assertThat(j.queryForObject("SELECT COUNT(*) FROM device_group_members",Long.class)).isEqualTo(1);}
    @Test void nameConstraintIsExactTenantScopedAndOnlyItsRealDriverIdentityTranslates(){var db=db(true);var j=db.jdbc();fixtures(j);group(j,UUID.randomUUID().toString(),"a","Case");assertThatThrownBy(()->group(j,UUID.randomUUID().toString(),"a","Case")).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(DeviceGroupConflicts.name(e)).isTrue());group(j,UUID.randomUUID().toString(),"a","case");group(j,UUID.randomUUID().toString(),"b","Case");String id=UUID.randomUUID().toString();group(j,id,"a","Other");assertThatThrownBy(()->group(j,id,"a","Another")).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(DeviceGroupConflicts.name(e)).isFalse());assertThatThrownBy(()->j.update("UPDATE device_groups SET revision=9007199254740992 WHERE id=?",id)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->j.update("UPDATE device_groups SET revision=-1 WHERE id=?",id)).isInstanceOf(DataAccessException.class);}
    @Test void latestRepeatedIsIdempotentWithExistingGroupMembershipAndAllCurrentFacts(){var db=db(true);var j=db.jdbc();fixtures(j);String id=UUID.randomUUID().toString();group(j,id,"a","Existing");j.update("INSERT INTO device_group_members(tenant_id,group_id,device_id) VALUES ('a',?,'legacy/a%?#')",id);var before=facts(j,tables(j));latest(db);latest(db);assertThat(facts(j,tables(j))).isEqualTo(before);assertThat(j.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='13' AND success=TRUE",Long.class)).isEqualTo(1);}
}
